// Validates and cleans the raw submission. Never throws: every outcome is
// routed by the next node so the website always gets a proper response.
const cfg = $('Config').first().json;
const req = $('Contact Form Webhook').first().json;
const body = req.body && typeof req.body === 'object' ? req.body : {};
const headers = req.headers ?? {};

const clean = (value) =>
  String(value ?? '')
    .replace(/<[^>]*>/g, '') // strip HTML tags
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '') // control chars, keeps newlines
    .trim();
const singleLine = (value, max) => clean(value).replace(/\s+/g, ' ').slice(0, max);
const result = (outcome, extra = {}) => [{ json: { outcome, ...extra } }];

if (cfg.formSecret && headers['x-form-secret'] !== cfg.formSecret) {
  return result('unauthorized', { error: 'Unauthorized' });
}

// Honeypot: a hidden field humans never see. Bots fill it in.
if (clean(body.website)) {
  return result('honeypot');
}

const lead = {
  name: singleLine(body.name, 200),
  email: singleLine(body.email, 254).toLowerCase(),
  phone: singleLine(body.phone, 50),
  company: singleLine(body.company, 200),
  message: clean(body.message),
};

const errors = [];
if (!lead.name) errors.push('Name is required.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(lead.email)) errors.push('A valid email address is required.');
if (!lead.message) errors.push('Message is required.');
if (lead.message.length > cfg.maxMessageLength) {
  errors.push(`Message must be ${cfg.maxMessageLength} characters or fewer.`);
}
if (errors.length) {
  return result('invalid', { error: errors.join(' ') });
}

return result('valid', {
  ...lead,
  leadId: `L-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`.toUpperCase(),
  submittedAt: new Date().toISOString(),
});

// Flags the lead as a duplicate if this email was already contacted (or is
// still being processed, e.g. a double-click) within the configured window.
// If the lookup failed, we treat the lead as new rather than lose it.
const cfg = $('Config').first().json;
const lead = $('Validate Submission').first().json;
const windowMs = cfg.duplicateWindowDays * 24 * 60 * 60 * 1000;

const previous = $input.all()
  .map((item) => item.json)
  .find((row) =>
    String(row.Email ?? '').toLowerCase() === lead.email &&
    ['New', 'Sent'].includes(row.Status) &&
    Date.now() - new Date(row['Submitted At']).getTime() < windowMs);

return [{
  json: {
    ...lead,
    isDuplicate: Boolean(previous),
    previousLeadId: previous?.['Lead ID'] ?? '',
  },
}];

