// Pulls the model's JSON out of the OpenAI response. If it is missing or
// malformed, falls back to a safe template so the lead still gets a reply.
const cfg = $('Config').first().json;
const lead = $('Check Duplicate').first().json;

const findReply = (value) => {
  if (value == null) return null;
  if (typeof value === 'string') {
    try { return findReply(JSON.parse(value)); } catch { return null; }
  }
  if (Array.isArray(value)) {
    for (const entry of value) {
      const found = findReply(entry);
      if (found) return found;
    }
    return null;
  }
  if (typeof value === 'object') {
    if (typeof value.is_spam === 'boolean') return value;
    for (const key of ['message', 'content', 'text', 'output', 'choices']) {
      const found = findReply(value[key]);
      if (found) return found;
    }
  }
  return null;
};

const ai = findReply($input.first().json);
const oneLine = (s) => String(s ?? '').replace(/[\r\n]+/g, ' ').trim().slice(0, 200);
const isUsable = ai && (ai.is_spam || (oneLine(ai.subject) && String(ai.body ?? '').trim()));

if (!isUsable) {
  const firstName = lead.name.split(' ')[0];
  return [{
    json: {
      isSpam: false,
      spamReason: '',
      usedFallback: true,
      subject: `Thanks for contacting ${cfg.businessName}`,
      body: [
        `Hi ${firstName},`,
        '',
        `Thank you for reaching out to ${cfg.businessName}. We've received your message and a member of our team will get back to you shortly.`,
        '',
        "If there's a good time for a quick call, just reply to this email and let us know.",
        '',
        'Best regards,',
        `The ${cfg.businessName} Team`,
      ].join('\n'),
    },
  }];
}

return [{
  json: {
    isSpam: ai.is_spam,
    spamReason: oneLine(ai.spam_reason),
    usedFallback: false,
    subject: oneLine(ai.subject),
    body: String(ai.body ?? '').trim(),
  },
}];

// Builds the Telegram summary for the owner. Values are escaped because the
// message uses Telegram's HTML formatting.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, max) => (s.length > max ? s.slice(0, max) + '…' : s);
const lead = $('Check Duplicate').first().json;
const ai = $('Parse AI Reply').isExecuted ? $('Parse AI Reply').first().json : null;

let status;
if (lead.isDuplicate) {
  status = `🔁 Duplicate: no email sent (already contacted as ${esc(lead.previousLeadId)})`;
} else if (ai?.isSpam) {
  status = `🚫 Flagged as spam: no email sent\n<i>${esc(ai.spamReason)}</i>`;
} else if (ai?.usedFallback) {
  status = '✅ Template follow-up sent (AI output was invalid)';
} else {
  status = '✅ AI follow-up sent';
}

const lines = [
  '<b>📥 New website lead</b>',
  status,
  '',
  `<b>Name:</b> ${esc(lead.name)}`,
  `<b>Email:</b> ${esc(lead.email)}`,
  lead.phone ? `<b>Phone:</b> ${esc(lead.phone)}` : null,
  lead.company ? `<b>Company:</b> ${esc(lead.company)}` : null,
  `<b>Lead ID:</b> ${esc(lead.leadId)}`,
  '',
  `<b>Message:</b>\n${esc(cut(lead.message, 1500))}`,
];
if (ai && !ai.isSpam && !lead.isDuplicate) {
  lines.push('', `<b>Email sent:</b> ${esc(ai.subject)}\n${esc(cut(ai.body, 1200))}`);
}

return [{ json: { text: lines.filter((line) => line !== null).join('\n') } }];

// A step failed even after retries. Alert the owner with the full lead so it
// can be followed up manually: no lead is ever lost.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, max) => (s.length > max ? s.slice(0, max) + '…' : s);
const lead = $('Check Duplicate').first().json;
const err = $json.error;
const errorMessage = String(
  (err && typeof err === 'object' ? err.message ?? JSON.stringify(err) : err) || $json.message || 'Unknown error',
);

const text = [
  `<b>⚠️ Lead workflow failed at: ${esc($json.failedStep)}</b>`,
  'Please follow up with this lead manually.',
  '',
  `<b>Name:</b> ${esc(lead.name)}`,
  `<b>Email:</b> ${esc(lead.email)}`,
  lead.phone ? `<b>Phone:</b> ${esc(lead.phone)}` : null,
  lead.company ? `<b>Company:</b> ${esc(lead.company)}` : null,
  `<b>Lead ID:</b> ${esc(lead.leadId)}`,
  '',
  `<b>Message:</b>\n${esc(cut(lead.message, 1500))}`,
  '',
  `<b>Error:</b> <code>${esc(cut(errorMessage, 500))}</code>`,
].filter((line) => line !== null).join('\n');

return [{ json: { failedStep: $json.failedStep, errorMessage, text } }];
